import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();

  // Load background texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;

  // Create background plane (512x320 atlas rect → 1.6:1 aspect)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1.0);
  const planeMaterial = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });

  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  container.add(planeMesh);

  // Add text label via font atlas
  const textObj = ctx.fontAtlas.createText('Journal 3', {
    fontSize: 0.34, // headline scale from type scale
    fontWeight: 400,
    fontFamily: 'Lora',
    color: 0xff2a38, // accent red
    align: 'center',
  });

  if (textObj) {
    textObj.position.z = 0.02;
    container.add(textObj);
  }

  // Apply scene placement
  container.position.set(3.2, 1, 0.06);
  container.rotation.set(0, 0, 0);
  container.scale.set(1, 1, 1);

  // Track GSAP timelines for cleanup
  const timelines = [];
  const baseY = 1;

  // Interaction handlers
  container.userData.handlers = {
    hover: {
      enter: () => {
        gsap.killTweensOf(container.position);
        const tl = gsap.to(container.position, {
          y: baseY + 0.15,
          duration: 0.7,
          ease: 'power3.out',
        });
        timelines.push(tl);
      },
      leave: () => {
        gsap.killTweensOf(container.position);
        const tl = gsap.to(container.position, {
          y: baseY,
          duration: 0.5,
          ease: 'power2.out',
        });
        timelines.push(tl);
      },
    },
    click: () => {
      gsap.killTweensOf(container.scale);
      const tl = gsap.timeline();
      tl.to(container.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      tl.to(container.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.15,
        ease: 'back.out',
      });
      timelines.push(tl);
    },
  };

  // Cleanup function
  container.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    planeGeometry.dispose();
    planeMaterial.dispose();
    texture.dispose();
  };

  return container;
}
